An alternative to <https://github.com/NixOS/nixpkgs/pull/324955>.

> genJqReplacementSnippet quotes the content of the secret file in the
> output json file, which prevents structured secret, such as a list or
> an object, from being used.

This PR adds a `quote = true|false` option to the `{ _secret = "/path/to/secret"; }` attribute set. `quote = true` threats the content of `/path/to/secret` as string, while `quote = false` threats the content of `/path/to/secret` as a JSON document.

`quote = true` is the default, so this PR maintains backward compatibility.

```nix
# demo.nix

let
  demoNixpkgs = fetchTarball "https://github.com/linyinfeng/nixpkgs/archive/refs/heads/json-secrets.zip";
  pkgs = import demoNixpkgs {};
  inherit (pkgs) lib;
  utils = import "${demoNixpkgs}/nixos/lib/utils.nix" {
    inherit lib pkgs;
    config = null;
  };
  settings = {
    example = [
      {
        irrelevant = "not interesting";
      }
      {
        ignored = "ignored attr";
        relevant = {
          secretString1 = {
            _secret = pkgs.writeText "password1" "secret-quote-1";
            # quote = true is the default
          };
          secretString2 = {
            _secret = pkgs.writeText "password2" "secret-quote-2";
            quote = true;
          };
          secretJson = {
            _secret = pkgs.writeText "password3" (builtins.toJSON {
              p1 = "supersecret";
              p2 = [2 3];
            });
            quote = false;
          };
        };
      }
    ];
  };
  snippet = utils.genJqSecretsReplacementSnippet settings;
in
pkgs.runCommand "test.json" {} ''
  ${snippet "result.json"}
  cp result.json "$out"
''
```

```console
$ nix-build ./demo.nix && cat result
/nix/store/36rgaa21gml1xl0lk3rdm28z3vw1rv84-test.json
{
  "example": [
    {
      "irrelevant": "not interesting"
    },
    {
      "ignored": "ignored attr",
      "relevant": {
        "secretJson": {
          "p1": "supersecret",
          "p2": [
            2,
            3
          ]
        },
        "secretString1": "secret-quote-1",
        "secretString2": "secret-quote-2"
      }
    }
  ]
}
```

